        internal static bool IsAllowed(ComponentId component, OpCode operation)
        {
            var required = RequiredCapability(operation);
            return required != 0 && (Capabilities(component) & required) == required;
        }

        internal static bool AllowsPayload(OpCode operation) => operation switch
        {
            OpCode.OnClick => true,
            OpCode.OnShortcut => true,
            OpCode.OverlayOnDismiss => true,
            _ => false,
        };

        internal static int PayloadError(OpCode operation, ulong a, ulong b) => operation switch
        {
            OpCode.ElementOwner when !(a >= 1UL) => -25,
            OpCode.ResourceOwner when !(a >= 1UL) => -25,
            OpCode.AlignContent when !(a <= 7UL) => -54,
            OpCode.FlexGrow when !(BitConverter.UInt32BitsToSingle((uint)a) >= 0f) => -46,
            OpCode.FlexShrink when !(BitConverter.UInt32BitsToSingle((uint)a) >= 0f) => -44,
            OpCode.FlexWrap when !(a <= 2UL) => -45,
            OpCode.AspectRatio when !(BitConverter.UInt32BitsToSingle((uint)a) > 0f) => -51,
            OpCode.BorderStyle when !(a <= 1UL) => -56,
            OpCode.Opacity when !(BitConverter.UInt32BitsToSingle((uint)a) >= 0f && BitConverter.UInt32BitsToSingle((uint)a) <= 1f) => -47,
            OpCode.Visibility when !(a <= 1UL) => -53,
            OpCode.FontStyle when !(a <= 1UL) => -22,
            OpCode.FontWeight when !(BitConverter.UInt32BitsToSingle((uint)a) >= 100f && BitConverter.UInt32BitsToSingle((uint)a) <= 900f) => -55,
            OpCode.LineClamp when !(a >= 1UL) => -49,
            OpCode.TextAlign when !(a <= 2UL) => -48,
            OpCode.WhiteSpace when !(a <= 1UL) => -52,
            OpCode.Checked when !(a <= 1UL) => -21,
            OpCode.Cursor when !(a <= 20UL) => -50,
            OpCode.Disabled when !(a <= 1UL) => -21,
            OpCode.IsolateShortcuts when !(a <= 1UL) => -21,
            OpCode.OnShortcut when !((b >> 27) == 0 && (b & 0xffff) >= 1 && (b & 0xffff) <= 86 && ((b >> 16) & 0xff) <= 63 && (((b & 0xffff) > 36 && (b & 0xffff) < 76 && (b & 0xffff) != 42) || (b & (41UL << 16)) != 0) && ((b & (32UL << 16)) == 0 || (b & (9UL << 16)) == 0)) => -66,
            OpCode.WindowControlArea when !(a <= 3UL) => -39,
            OpCode.FocusTabStop when !(a <= 1UL) => -21,
            OpCode.ScrollAxis when !(a <= 2UL) => -26,
            OpCode.ScrollbarGutter when !(a <= 1UL) => -21,
            OpCode.ScrollbarWidth when !(BitConverter.UInt32BitsToSingle((uint)a) >= 3f && BitConverter.UInt32BitsToSingle((uint)a) <= 32f) => -29,
            OpCode.ShowScrollbar when !(a <= 1UL) => -21,
            OpCode.SmoothScroll when !(a <= 1UL) => -21,
            OpCode.ListAlignment when !(a <= 1UL) => -28,
            OpCode.ListBatchSize when !(a >= 1UL && a <= 512UL) => -27,
            OpCode.ListEstimatedItemExtentPx when !(BitConverter.UInt32BitsToSingle((uint)a) > 0f) => -29,
            OpCode.ListOverdrawPx when !(BitConverter.UInt32BitsToSingle((uint)a) >= 0f) => -29,
            OpCode.ItemTooltipTarget when !(a <= 1UL) => -21,
            OpCode.ListOrientation when !(a <= 1UL) => -28,
            OpCode.TableColumn when !((a >> 36) == 0 && ((a >> 32) & 0b11) <= 1 && ((a >> 34) & 0b11) <= 2 && float.IsFinite(BitConverter.UInt32BitsToSingle((uint)a)) && BitConverter.UInt32BitsToSingle((uint)a) > 0f && (((a >> 32) & 0b11) != 1 || BitConverter.UInt32BitsToSingle((uint)a) <= 1f)) => -57,
            OpCode.InputDisabled when !(a <= 1UL) => -21,
            OpCode.InputPassword when !(a <= 1UL) => -21,
            OpCode.InputReadOnly when !(a <= 1UL) => -21,
            OpCode.SliderAxis when !(a <= 1UL) => -43,
            OpCode.SliderDisabled when !(a <= 1UL) => -21,
            OpCode.SliderScale when !(a <= 1UL) => -43,
