            OpCode.OverlayModal when !(a <= 1UL) => -21,
            OpCode.OverlayPlacement when !(a <= 8UL) => -33,
            OpCode.TooltipAlignment when !(a <= 2UL) => -36,
            OpCode.TooltipGapPx when !(BitConverter.UInt32BitsToSingle((uint)a) >= 0f) => -37,
